func minCostII(costs [][]int) int {
	n, k := len(costs), len(costs[0])
	f := cp(costs[0])
	for i := 1; i < n; i++ {
		g := cp(costs[i])
		for j := 0; j < k; j++ {
			t := math.MaxInt32
			for h := 0; h < k; h++ {
				if h != j && t > f[h] {
					t = f[h]
				}
			}
			g[j] += t
		}
		f = g
	}
	return slices.Min(f)
}

func cp(arr []int) []int {
	t := make([]int, len(arr))
	copy(t, arr)
	return t
}

class Solution:
    def minCostII(self, costs):
        """
        :type costs: List[List[int]]
        :rtype: int
        """
        if len(costs) == 0: return 0

        for i in range(1, len(costs)):
            sortedArr = sorted(costs[i - 1])
            for j in range(len(costs[0])):
                costs[i][j] += sortedArr[0] if costs[i - 1][j] != sortedArr[0] else sortedArr[1]

        return min(costs[-1])

import sys
class Solution(object):
    def minCostII(self, costs):
        """
        :type costs: List[List[int]]
        :rtype: int
        """

        if not costs:
            return 0
        self.costs = costs
        self.memo = {}
        self.k = len(costs[0])
        mincost = sys.maxint
        for i in range(self.k):
            mincost = min(mincost, self.recurse(0, i))
        return mincost

    def recurse(self, start_index, color):
        if start_index==len(self.costs):
            return 0
        if (start_index, color) not in self.memo:
            cost = self.costs[start_index][color]
            _min = sys.maxint
            for c in range(self.k):
                if c!=color or start_index+1==len(self.costs):
                    _min = min(_min, self.recurse(start_index+1, c))
            self.memo[(start_index, color)] = cost+_min
        return self.memo[(start_index, color)]

