class Solution(object):
    def minCostII(self, costs):
        """
        :type costs: List[List[int]]
        :rtype: int
        """
        if len(costs) == 0 or len(costs[0]) == 0:
            return 0
        n, k = len(costs), len(costs[0])
        dp = [[0 for _ in range(k)] for _ in range(n)]
        prev_min = float("inf")
        prev_min_index = -1
        prev_second_min = float("inf")
        for i in range(n):
            for j in range(k):
                if i == 0:
                    dp[i][j] = costs[i][j]
                elif j == prev_min_index:
                    dp[i][j] = prev_second_min + costs[i][j]
                else:
                    dp[i][j] = prev_min + costs[i][j]
            prev_min = float("inf")
            prev_min_index = -1
            prev_second_min = float("inf")
            for j in range(k):
                if dp[i][j] < prev_min:
                    prev_second_min = prev_min
                    prev_min = dp[i][j]
                    prev_min_index = j
                elif dp[i][j] < prev_second_min:
                    prev_second_min = dp[i][j]
        return min(dp[-1])
